def make_pair(h,w,bbox,frame,corebox,fill,pad):
    r0,r1,c0,c1=bbox; a,b,x,y=corebox
    g=[[0]*w for _ in range(h)]
    for r in range(r0,r1+1):
        for c in range(c0,c1+1): g[r][c]=frame
    for r in range(a,b+1):
        for c in range(x,y+1): g[r][c]=fill
    e=[[0]*w for _ in range(h)]
    for r in range(max(0,r0-pad),min(h,r1+pad+1)):
        for c in range(max(0,c0-pad),min(w,c1+pad+1)): e[r][c]=fill
    for r in range(h):
        for c in range(w):
            if g[r][c]: e[r][c]=g[r][c]
    return {'input':g,'expected':e}
